public interface ItemProcessor<I, O> {
    O process(I item) throws Exception;
}

@Component
public class UpperCaseNameItemProcessor implements ItemProcessor<Employee, Employee> {

    @Override
    public Employee process(Employee item) throws Exception {
        // Transform employee name to uppercase
        item.setEmpName(item.getEmpName().toUpperCase());
        return item;
    }
}

@Bean
public Step employeeJdbcJsonStep() {
    return stepBuilderFactory.get("employeeJdbcJsonStep")
            .<Employee, Employee>chunk(3)  // process 3 items per transaction
            .reader(jdbcEmployeeItemReader) // ItemReader reads from DB
            .processor(upperCaseNameItemProcessor) // Transform names
            .writer(jsonFileItemWriter)    // Write to JSON file
            .build();
}

